void mainImage(out vec4 cf, vec2 CF) {
    vec2 UVN = (CF + CF - iResolution.xy) / iResolution.y;

    cf = vec4(0.);

    float T = iTime * 2.;
    float IP = 6000.;
    float OR, HZ, DC, PO;

    for (; IP >= 0.; IP -= 20. / 3.) {
        OR = 5. * cos(IP / 44.);
        HZ = IP / 506. - 15.;
        DC = length(vec2(OR, HZ)) / 3.;
        PO = DC / 2. - T / 3. + mod(IP, 2.) * 3.;

        float CX = (93.22 + DC * DC + OR * OR) * sin(PO) 
                         + DC * DC * DC / 4. * cos(T * 3. - DC * DC / 4.);

        float CY = -99. * cos(PO / 2.) 
                         - 4. * sin(OR + OR) 
                         - IP * OR * HZ / 19481. / sin(HZ / 2.);

        vec2 PP = vec2(CX, CY) / 160.8;

        vec3 CP = 0.5 + 0.299 * cos(PO + T + vec3(0., 1., 2.));
        float RG = length(UVN - PP) + 0.001;

        cf.rgb += CP * (0.000468 / RG);
    }

    cf = pow(cf, vec4(1.7));
}
